     2	import type { Database } from "bun:sqlite";
     3	
     4	const HOUR = 60 * 60 * 1000;
     5	
     6	type JobRow = {
     7	  job_id: string;
     8	  bike_id: string;
     9	  station_id: string;
    10	  source: string;
    11	  fault: string;
    12	  reported_at: string;
    13	  opened_at: string;
    14	};
    15	
    16	// The contract limit: 48 hours for a wrench, 96 hours for a defect a crew found itself.
    17	// The clock runs from when the dispatch desk opened the job.
    18	function contractDeadline(job: JobRow): string {
    19	  const limitHours = job.source === "wrench" ? 48 : 96;
    20	  return new Date(Date.parse(job.opened_at) + limitHours * HOUR).toISOString();
    21	}
    22	
    23	export function crewQueue(database: Database, depot: string | null) {
    24	  const jobs = database
    25	    .query("SELECT * FROM repair_jobs WHERE closed_at IS NULL AND (?1 IS NULL OR depot = ?1)")
    26	    .all(depot) as JobRow[];
    27	  // Oldest job first, the way the dispatch desk has always worked.
    28	  jobs.sort((first, second) => first.opened_at.localeCompare(second.opened_at));
    29	  const queue = jobs.map((job) => ({ ...job, deadline: contractDeadline(job) }));
    30	  return { depot: depot ?? "all", jobs: queue };
    31	}
