     1	// spoke's database: stations, bikes, wrenches and repair jobs, in one SQLite file.
     2	// When the file is new, it is filled from the CSV files in data/.
     3	import { Database } from "bun:sqlite";
     4	import { existsSync } from "node:fs";
     5	import { join } from "node:path";
     6	import { readCsv } from "./csv";
     7	
     8	const DATA_FOLDER = join(import.meta.dir, "..", "data");
     9	const DATABASE_FILE = process.env.SPOKE_DB ?? join(import.meta.dir, "..", "spoke.db");
    10	const HOUR = 60 * 60 * 1000;
    11	
    12	const TABLES = `
    13	  CREATE TABLE stations (station_id TEXT PRIMARY KEY, name TEXT, district TEXT, depot TEXT,
    14	    x INTEGER, y INTEGER, docks INTEGER);
    15	  CREATE TABLE bikes (bike_id TEXT PRIMARY KEY, bike_type TEXT, station_id TEXT,
    16	    is_disabled INTEGER DEFAULT 0);
    17	  CREATE TABLE wrenches (wrench_id INTEGER PRIMARY KEY AUTOINCREMENT, bike_id TEXT,
    18	    station_id TEXT, fault TEXT, reported_at TEXT);
    19	  CREATE TABLE repair_jobs (job_id TEXT PRIMARY KEY, bike_id TEXT, station_id TEXT, depot TEXT,
    20	    source TEXT, fault TEXT, reported_at TEXT, opened_at TEXT, closed_at TEXT);
    21	`;
    22	
    23	function fillStationsAndBikes(database: Database) {
    24	  const addStation = database.prepare("INSERT INTO stations VALUES (?, ?, ?, ?, ?, ?, ?)");
    25	  for (const station of readCsv(join(DATA_FOLDER, "stations.csv"))) {
    26	    const mapPosition = [Number(station.x), Number(station.y)];
    27	    const where = [station.station_id, station.name, station.district, station.depot];
    28	    addStation.run(...where, ...mapPosition, Number(station.docks));
    29	  }
    30	  const addBike = database.prepare("INSERT INTO bikes VALUES (?, ?, ?, 0)");
    31	  for (const bike of readCsv(join(DATA_FOLDER, "bikes.csv"))) {
    32	    addBike.run(bike.bike_id, bike.bike_type, bike.station_id);
    33	  }
    34	}
    35	
    36	// Open jobs are stored as "hours ago", so the queue looks fresh whenever spoke starts.
    37	function fillOpenJobs(database: Database) {
    38	  const now = Date.now();
    39	  const addJob = database.prepare("INSERT INTO repair_jobs VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL)");
    40	  const disableBike = database.prepare(
    41	    "UPDATE bikes SET is_disabled = 1, station_id = ? WHERE bike_id = ?",
    42	  );
    43	  for (const job of readCsv(join(DATA_FOLDER, "open-jobs.csv"))) {
    44	    const reportedAt = new Date(now - Number(job.reported_hours_ago) * HOUR).toISOString();
    45	    const openedAt = new Date(now - Number(job.opened_hours_ago) * HOUR).toISOString();
    46	    const { job_id, bike_id, station_id, depot, source, fault } = job;
    47	    addJob.run(job_id, bike_id, station_id, depot, source, fault, reportedAt, openedAt);
    48	    disableBike.run(station_id, bike_id);
    49	  }
    50	}
    51	
    52	export function openDatabase(): Database {
    53	  const isNew = !existsSync(DATABASE_FILE);
    54	  const database = new Database(DATABASE_FILE);
    55	  if (isNew) {
    56	    database.exec(TABLES);
    57	    fillStationsAndBikes(database);
    58	    fillOpenJobs(database);
    59	  }
    60	  return database;
    61	}
