     1	// The public feed in GBFS v3 shape: https://github.com/MobilityData/gbfs/blob/master/gbfs.md
     2	// Rider apps and the city read it. The contract says it must be accurate at all times.
     3	import type { Database } from "bun:sqlite";
     4	
     5	const FEED_VERSION = "3.0";
     6	const SECONDS_UNTIL_STALE = 60;
     7	
     8	type BikeRow = { bike_id: string; bike_type: string; station_id: string; is_disabled: number };
     9	type StationCount = { station_id: string; docks: number; available: number; disabled: number };
    10	
    11	function wrapInFeed(data: object) {
    12	  const lastUpdated = new Date().toISOString();
    13	  return { last_updated: lastUpdated, ttl: SECONDS_UNTIL_STALE, version: FEED_VERSION, data };
    14	}
    15	
    16	export function vehicleStatus(database: Database) {
    17	  const bikes = database.query("SELECT * FROM bikes ORDER BY bike_id").all() as BikeRow[];
    18	  const vehicles = bikes.map((bike) => ({
    19	    vehicle_id: bike.bike_id,
    20	    station_id: bike.station_id,
    21	    vehicle_type_id: bike.bike_type,
    22	    is_reserved: false,
    23	    is_disabled: bike.is_disabled === 1,
    24	  }));
    25	  return wrapInFeed({ vehicles });
    26	}
    27	
    28	const STATION_COUNTS = `
    29	  SELECT stations.station_id, stations.docks,
    30	    SUM(CASE WHEN bikes.is_disabled = 0 THEN 1 ELSE 0 END) AS available,
    31	    SUM(CASE WHEN bikes.is_disabled = 1 THEN 1 ELSE 0 END) AS disabled
    32	  FROM stations LEFT JOIN bikes ON bikes.station_id = stations.station_id
    33	  GROUP BY stations.station_id ORDER BY stations.station_id`;
    34	
    35	export function stationStatus(database: Database) {
    36	  const counts = database.query(STATION_COUNTS).all() as StationCount[];
    37	  const stations = counts.map((count) => ({
    38	    station_id: count.station_id,
    39	    num_vehicles_available: count.available ?? 0,
    40	    num_vehicles_disabled: count.disabled ?? 0,
    41	    num_docks_available: Math.max(0, count.docks - (count.available ?? 0) - (count.disabled ?? 0)),
    42	    is_renting: true,
    43	    is_returning: true,
    44	  }));
    45	  return wrapInFeed({ stations });
    46	}
