     7	const DISTRICT_COLOURS: Record<string, string> = {
     8	  North: "#3b82f6",
     9	  East: "#14b8a6",
    10	  Centre: "#a855f7",
    11	  South: "#f59e0b",
    12	  West: "#22c55e",
    13	};
    14	
    15	function stationDot(station: StationRow, brokenBikes: number): string {
    16	  const colour = DISTRICT_COLOURS[station.district] ?? "#888";
    17	  const dot = `<circle cx="${station.x}" cy="${station.y}" r="9" fill="${colour}">`;
    18	  const title = `<title>${station.station_id} ${station.name}</title></circle>`;
    19	  if (brokenBikes === 0) return dot + title;
    20	  const badge = `<circle cx="${station.x + 9}" cy="${station.y - 9}" r="8" fill="#dc2626"/>`;
    21	  const count = `<text x="${station.x + 9}" y="${station.y - 5}">${brokenBikes}</text>`;
    22	  return dot + title + badge + count;
    23	}
    24	
    25	function legend(totalBroken: number, totalAvailable: number): string {
    26	  const districts = Object.entries(DISTRICT_COLOURS)
    27	    .map(([name, colour]) => `<span><i style="background:${colour}"></i>${name}</span>`)
    28	    .join("");
    29	  return `<p class="legend">${districts}</p>
    30	    <p><b>${totalAvailable}</b> bikes riders can rent. <b class="red">${totalBroken}</b> broken
    31	    bikes out of service. Red numbers show broken bikes waiting at a station.</p>`;
    32	}
    33	
    34	const STYLE = `body{font-family:system-ui,sans-serif;margin:24px;background:#f8fafc;color:#0f172a}
    35	  h1{margin:0 0 4px}svg{background:#fff;border:1px solid #cbd5e1;border-radius:8px}
    36	  text{font-size:10px;fill:#fff;text-anchor:middle;font-weight:700}
    37	  .legend span{margin-right:14px}.legend i{display:inline-block;width:10px;height:10px;
    38	  border-radius:50%;margin-right:4px}.red{color:#dc2626}`;
    39	
    40	export function mapPage(database: Database): string {
    41	  const stations = database.query("SELECT * FROM stations").all() as StationRow[];
    42	  const feed = stationStatus(database).data.stations;
    43	  const brokenAt = new Map(feed.map((entry) => [entry.station_id, entry.num_vehicles_disabled]));
    44	  const dots = stations.map((station) =>
    45	    stationDot(station, brokenAt.get(station.station_id) ?? 0),
    46	  );
    47	  const totalBroken = feed.reduce((sum, entry) => sum + entry.num_vehicles_disabled, 0);
    48	  const totalAvailable = feed.reduce((sum, entry) => sum + entry.num_vehicles_available, 0);
    49	  return `<!doctype html><html><head><meta charset="utf-8"><title>Kestrel Bike Share</title>
    50	    <style>${STYLE}</style></head><body><h1>Kestrel Bike Share: Brannock</h1>
    51	    ${legend(totalBroken, totalAvailable)}
    52	    <svg width="940" height="660" viewBox="0 0 940 660">${dots.join("")}</svg></body></html>`;
    53	}
