     1	// POST /wrench: a rider pressed the wrench button in the app to report a broken bike.
     2	import type { Database } from "bun:sqlite";
     3	import { logEvent } from "./log";
     4	
     5	type WrenchReport = { bike_id?: string; fault?: string };
     6	type BikeRow = { bike_id: string; station_id: string };
     7	type StationRow = { depot: string };
     8	
     9	export function recordWrench(database: Database, report: WrenchReport) {
    10	  const bike = database.query("SELECT * FROM bikes WHERE bike_id = ?").get(report.bike_id ?? "");
    11	  if (!bike) return { status: 404, body: { error: `no bike called ${report.bike_id}` } };
    12	  const { bike_id, station_id } = bike as BikeRow;
    13	  const station = database.query("SELECT depot FROM stations WHERE station_id = ?").get(station_id);
    14	  const reportedAt = new Date().toISOString();
    15	  const fault = report.fault ?? "OTHER";
    16	
    17	  database
    18	    .query("INSERT INTO wrenches (bike_id, station_id, fault, reported_at) VALUES (?, ?, ?, ?)")
    19	    .run(bike_id, station_id, fault, reportedAt);
    20	
    21	  // A dispatcher opens the repair job from the wrench.
    22	  const jobId = `J-${Date.now()}`;
    23	  const depot = (station as StationRow).depot;
    24	  database
    25	    .query("INSERT INTO repair_jobs VALUES (?, ?, ?, ?, 'wrench', ?, ?, ?, NULL)")
    26	    .run(jobId, bike_id, station_id, depot, fault, reportedAt, reportedAt);
    27	
    28	  logEvent("wrench", { bike_id, station_id, fault, job_id: jobId });
    29	  return { status: 201, body: { job_id: jobId, bike_id } };
    30	}
